<?php if(isset($_GET['updated'])): ?><div class="notice notice-success inline"><p>Robots settings saved.</p></div><?php endif; ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="seom-panel"><input type="hidden" name="action" value="seom_save_robots"><?php wp_nonce_field('seom_save_robots'); ?><h2>Robots & Crawl Controls</h2><p class="description">Control indexability and custom robots.txt rules without blocking the whole site by mistake.</p><div class="seom-toggle-grid"><label><input type="checkbox" name="search_noindex" value="1" <?php checked((int)seom_get('search_noindex',1),1); ?>> Noindex internal search results</label><label><input type="checkbox" name="date_noindex" value="1" <?php checked((int)seom_get('date_noindex',1),1); ?>> Noindex date archives</label><label><input type="checkbox" name="author_noindex" value="1" <?php checked((int)seom_get('author_noindex',0),1); ?>> Noindex author archives</label><label><input type="checkbox" name="category_noindex" value="1" <?php checked((int)seom_get('category_noindex',0),1); ?>> Noindex category archives</label><label><input type="checkbox" name="tag_noindex" value="1" <?php checked((int)seom_get('tag_noindex',1),1); ?>> Noindex tag archives</label></div><label class="seom-full-label">Custom robots.txt rules<textarea name="robots_custom" rows="10" class="widefat"><?php echo esc_textarea(seom_get('robots_custom','')); ?></textarea><small>Keep this empty to use WordPress defaults. Review Disallow rules carefully before saving.</small></label><p><button class="button button-primary">Save Crawl Settings</button></p></form>